#!/usr/bin/env python3
"""Generate <fw>/CONFORMANCE.md from the raw outputs in <fw>/conformance-out/ (W5).
Usage: python3 w5_report.py <fw>   (run from binding/harness/executors)"""
import json, os, sys

fw = sys.argv[1]
base = os.path.join(fw, "conformance-out")
CFGS = [("off", "off"), ("off", "origin-raw"), ("off", "origin-routed"),
        ("on", "off"), ("on", "origin-raw"), ("on", "origin-routed")]
out = [f"# {fw}: conformance results\n",
       "Generated by `spring/tools/w5_report.py` from the raw files in `conformance-out/` (nothing is hand-edited).",
       "Test: W4's `conformance/run_conformance.py`, driven by `spring/tools/w5_conformance.sh` (image `bh-exec-"
       f"{fw}:latest`, W4's `stub_verifier.py` running as container `w5-verifier` with alias `verifier` on network `w5-net`).\n",
       "| OVERRIDE | VERIFY_MODE | required checks | failures |", "|---|---|---|---|"]
details = []
for ov, vm in CFGS:
    p = os.path.join(base, f"ov{ov}_{vm}", "result.json")
    if not os.path.exists(p):
        out.append(f"| {ov} | {vm} | not run | |"); continue
    r = json.load(open(p))
    fails = [c["case"] for c in r["required"] if not (c["ok"] and c["log_ok"])]
    fails += [f"verify[{v['case']}]: {'; '.join(v['errors'])}" for v in r.get("verify", []) if not v["ok"]]
    if r["trust"] and not r["trust"]["ok"]: fails.append("trust-header capture")
    if not r["jti_null"]["ok"]: fails.append("jti=null")
    out.append(f"| {ov} | {vm} | {r['passed']}/{r['total']} | {'<br>'.join(fails) or '-'} |")
    if r.get("override"):
        details.append(f"\n**Override probes, OVERRIDE={ov} VERIFY_MODE={vm}** (informational)\n")
        details.append("| probe | request | status | op_id |\n|---|---|---|---|")
        for o in r["override"]:
            details.append(f"| {o['probe']} | `{o['method']} {o['target']}` | {o['status']} | {o['op_id']} |")
    for v in r.get("verify", []):
        vw = v.get("view") or {}
        details.append(f"- verify[{vm}, OVERRIDE={ov}] {v['case']}: status {v['status']}, op_id {v['op_id']}, "
                       f"view `{vw.get('x_original_method')} {vw.get('x_original_uri')}` host `{vw.get('x_original_host')}`, "
                       f"Authorization fwd {vw.get('authorization')}, DPoP fwd {vw.get('dpop')} -> {'PASS' if v['ok'] else 'FAIL: ' + '; '.join(v['errors'])}")
out += ["", "## Details (from result.json)"] + details
for ov in ("off", "on"):
    p = os.path.join(base, f"probes_ov{ov}.md")
    if os.path.exists(p):
        out += ["", f"## Router-normalisation probes, OVERRIDE={ov}",
                "Raw-socket probes (`spring/tools/normalisation_probes.py`, VERIFY_MODE=off). Evidence for README, not pass/fail.", "",
                open(p).read().split("\n", 2)[2]]
notes = os.path.join(base, "notes.md")
if os.path.exists(notes):
    out = out[:3] + [open(notes).read(), ""] + out[3:]
open(os.path.join(fw, "CONFORMANCE.md"), "w").write("\n".join(out) + "\n")
print("wrote", os.path.join(fw, "CONFORMANCE.md"))
